ListNode* current = head;
ListNode* previous = nullptr;
bool found = false;

while (current != nullptr) {
    if (current->val == value) {
        found = true;
        if (previous == nullptr) {
            // Node to remove is the head
            head = current->next;
            delete current;
            current = head;
        } else {
            previous->next = current->next;
            delete current;
            current = previous->next;
        }
    } else {
        previous = current;
        current = current->next;
    }
}

return found;

